/// <summary>
/// METTierRatecalulation UI builder class
/// </summary>
class METTierRateCalculationsUIBuilder extends SysOperationAutomaticUIBuilder
{
    private DialogField dialogFieldDateFrom;
    private DialogField dialogFieldRebateDeal;
    str rebateDeal;

}

Method.Source:
    /// <summary>
    /// Post 
    /// </summary>
    public void postBuild()
    {
        super();

        //from date
        dialogFieldDateFrom = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(METTierRateCalculationContract, parmFromDate));
       
        dialogFieldRebateDeal = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(METTierRateCalculationContract, parmRebateDealRecId));
        
        rebateDeal = dialogFieldRebateDeal.value();
        
    }

/// <summary>
/// Post run method
/// </summary>
public void postRun()
{
    super();
    // register overrides for form control events
    dialogFieldDateFrom.registerOverrideMethod(methodstr(FormDateControl, validate),
                                               methodstr(METTierRateCalculationsUIBuilder, validateDate), this);
}

    /// <summary>
    /// Validate to date range
    /// </summary>
    /// <param name = "_dateControl">from date control</param>
    /// <returns>true or false</returns>
    public boolean validateDate(FormDateControl _dateControl)
    {
        boolean ret = true;

        if (_dateControl.dateValue() && rebateDeal)
        {
            TAMRebateDate rebateDate;
            TAMRebateTable rebateTable;

            RefRecId rebateDealRefRecid = TAMRebateDeal::findByName(rebateDeal).RecId;

            select firstonly RebateId from rebateTable
                where rebateTable.RebateDeal == rebateDealRefRecid
                    && rebateTable.METTierLineType == METTierLineType::Value
                join RebateFromDate from rebateDate
                    where rebateDate.RebateId == rebateTable.RebateId;
                           
            if (_dateControl.dateValue() < rebateDate.RebateFromDate)
            {
                error("@MET:FromDateLessThanDealStartDate");
                boolean ret = true;
            }
        }

        return ret;
    }
